'use strict';
// Public card IDs only; no authenticated account or customer data in this gallery.
const showcaseDesignURL="/showcase-designs.json";
let showcaseDesigns=approvedShowcaseDesigns,showcaseRequest=null;
const showcaseReady=new Set(),showcaseLoading=new Map();
function loadShowcaseImage(src){if(!src)return Promise.resolve(true);if(showcaseReady.has(src))return Promise.resolve(true);if(showcaseLoading.has(src))return showcaseLoading.get(src);const job=new Promise(resolve=>{let attempts=0;const image=new Image();image.decoding='async';image.onload=async()=>{try{await image.decode();}catch{}showcaseReady.add(src);resolve(true);};image.onerror=()=>{if(++attempts<3)setTimeout(()=>{image.src=src;},attempts*1200);else{showcaseLoading.delete(src);resolve(false);}};image.src=src;});showcaseLoading.set(src,job);return job;}
function prepareShowcaseImages(){const urls=new Set(showcaseDesigns.flatMap(c=>[c.background,c.logo,c.stampImage,c.stampEmptyImage,c.rewardImage]).filter(Boolean));urls.forEach(loadShowcaseImage);}
prepareShowcaseImages();
let galleryWalletMode='apple';
const beforePortraitHome=homeHTML;
function walletDeviceCard(c,step=2){const native=galleryCard(c,step,true);let pass=native;if(galleryWalletMode==='google'){const box=document.createElement('div');box.innerHTML=native;const take=selector=>box.querySelector(selector)?.outerHTML||'';pass='<div class="studio-card google-pass" style="--card:'+esc(c.color)+';--accent:'+esc(c.accent)+'"><div class="google-pass-head">'+take('.wallet-logo')+take('.wallet-balance')+'</div><div class="google-hero"><div class="google-art">'+take('.studio-background')+take('.studio-stamps')+'</div></div>'+take('.studio-code')+take('.studio-bottom')+'</div>';}
return '<div class="device-frame '+galleryWalletMode+'-device"><div class="device-camera" aria-hidden="true"></div><div class="device-status" aria-hidden="true"><span>9:41</span><span>▮▮　◔　▰</span></div><div class="device-app-title">'+(galleryWalletMode==='apple'?'Wallet':'Google Wallet')+'</div><div class="device-pass">'+pass+'</div><div class="device-home" aria-hidden="true"></div></div>';}
function walletModeControls(){return '<div class="wallet-preview-controls" role="group" aria-label="معاينة المحفظة"><button type="button" data-gallery-wallet="apple" aria-pressed="'+(galleryWalletMode==='apple')+'"><span aria-hidden="true">'+applePreviewIcon+'</span>Apple Wallet</button><button type="button" data-gallery-wallet="google" aria-pressed="'+(galleryWalletMode==='google')+'"><span class="google-mark" aria-hidden="true">G</span>Google Wallet</button><p>معاينة توضيحية؛ قد يختلف العرض الفعلي حسب المحفظة وإصدار النظام.</p></div>';}
const applePreviewIcon='<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><path d="M17.1 12.4c0-2 1.6-3 1.7-3.1-1-1.4-2.5-1.6-3-1.7-1.3-.1-2.5.8-3.2.8-.6 0-1.6-.8-2.7-.7-1.4 0-2.7.8-3.4 2-1.5 2.5-.4 6.3 1 8.3.7 1 1.4 2 2.5 2 1 0 1.4-.7 2.7-.7s1.7.7 2.8.7c1.2 0 1.9-1 2.5-2 .8-1.1 1.1-2.2 1.1-2.3-.1 0-2-.8-2-3.3ZM15 6.4c.6-.8 1.1-1.9 1-3-.9 0-2 .6-2.7 1.4-.6.6-1.2 1.7-1.1 2.8 1 .1 2.1-.5 2.8-1.2Z"/></svg>';
function galleryCard(c,step=2,full=true){const p=Loyalty.program(c),member={showcasePreview:true,id:'RJ-PREVIEW01',name:c.cardLanguage==='en'?'Card preview':'معاينة البطاقة',stamps:step,points:p.type==='points'?step*p.pointsPerVisit:0,rewards:0};return cardHTML(c,member,full);}
function portraitMarkup(designs){return '<div class="portrait-space" aria-hidden="true"></div><div class="portrait-deck">'+designs.map((c,i)=>`<figure class="portrait-card" data-index="${i}" tabindex="0" role="button" aria-label="${esc(c.title||c.name||'بطاقة الولاء')}" aria-pressed="${i===1}"><div class="portrait-face">${walletDeviceCard(c)}</div></figure>`).join('')+'</div>';}
homeHTML=function(){const box=document.createElement('div');box.innerHTML=beforePortraitHome();box.querySelectorAll('.gallery-heading,.gallery-hint').forEach(el=>el.remove());const intro=box.querySelector('.hero-copy>p:not(.landing-kicker)');if(intro)intro.textContent='زيارات، خصومات أو نقاط. صمّم بطاقاتك، أدر فروعك وفريقك، وتابع الزيارات والمكافآت من مكان واحد. وتصميم بطاقتك الأولى علينا.';const stage=box.querySelector('.media-gallery');if(stage){stage.className='media-gallery portrait-gallery';stage.setAttribute('role','region');stage.setAttribute('aria-label','معرض بطاقات ثلاثي الأبعاد، اسحب أو استخدم الأسهم للتنقل');stage.insertAdjacentHTML('beforebegin',walletModeControls());stage.innerHTML=showcaseDesigns?portraitMarkup(showcaseDesigns):'<div class="portrait-space" aria-hidden="true"></div>';stage.insertAdjacentHTML('afterend','<div class="first-card-design"><span class="first-design-label">بداية تليق بنشاطك</span><h2>تصميم بطاقتك الأولى علينا</h2><p>نصمّم لك بطاقة ولاء بهوية نشاطك، بعناية في كل تفصيل.</p></div>');}const footer=box.querySelector('.public-footer');if(footer)footer.outerHTML='<footer class="info-footer"><div><strong>رِجعة</strong><p>كل زيارة، فرصة للرجعة.</p></div><nav aria-label="روابط المعلومات"><a href="/support.html">الدعم والتذاكر</a><a href="/about.html">عن رِجعة</a><a href="/guide.html">دليل الاستخدام</a><a href="/faq.html">الأسئلة الشائعة</a><a href="/billing.html">الاشتراك والاسترداد</a><a href="/terms.html">شروط الاستخدام</a><a href="/privacy.html">سياسة الخصوصية</a><a href="/contact.html">تواصل معنا</a></nav><small>© ٢٠٢٦ رِجعة · نظام الولاء</small></footer>';return box.innerHTML;};
const beforePortraitBind=bindGallery;
bindGallery=function(){
 const stage=document.querySelector('.portrait-gallery');if(!stage)return beforePortraitBind();
 if(!showcaseDesigns){showcaseRequest||=fetch(showcaseDesignURL).then(r=>{if(!r.ok)throw Error('Showcase unavailable');return r.json();}).then(data=>{if(!Array.isArray(data)||data.length<1)throw Error('Invalid showcase');showcaseDesigns=data;});showcaseRequest.then(()=>{if(!stage.isConnected)return;stage.innerHTML=portraitMarkup(showcaseDesigns);bindGallery();}).catch(()=>{stage.setAttribute('aria-label','تعذر تحميل معرض البطاقات');showcaseRequest=null;});return;}
 stage.querySelectorAll('img').forEach(img=>{img.decoding='async';img.addEventListener('load',()=>{img.style.visibility='';});function recover(){const src=img.getAttribute('src');img.style.visibility='hidden';if(showcaseReady.delete(src))showcaseLoading.delete(src);loadShowcaseImage(src).then(ok=>{if(!stage.isConnected||!ok)return;img.src=src;if(img.complete&&img.naturalWidth)img.style.visibility='';});}img.addEventListener('error',recover);if(!img.complete||!img.naturalWidth){img.style.visibility='hidden';loadShowcaseImage(img.getAttribute('src')).then(ok=>{if(!stage.isConnected||!ok)return;if(img.complete&&img.naturalWidth)img.style.visibility='';else img.src=img.getAttribute('src');});}});
 const cards=[...stage.querySelectorAll('.portrait-card')],reduce=matchMedia('(prefers-reduced-motion: reduce)');
 let frame=0,alive=true,index=0,drag=null,tiltX=0,tiltY=0,dragOffset=0,suppressClick=false;
 document.querySelectorAll('[data-gallery-wallet]').forEach(button=>button.addEventListener('click',()=>{if(galleryWalletMode===button.dataset.galleryWallet)return;galleryWalletMode=button.dataset.galleryWallet;render();}));stage.tabIndex=0;stage.classList.toggle('gallery-four',cards.length===4);
 const pricing=document.querySelector('.landing .pricing');
 let width=0,cardWidth=0,spacing=0,pricingTop=0;
 function select(next){index=Math.max(0,Math.min(cards.length-1,next));cards.forEach((card,i)=>{const active=i===index;card.classList.toggle('is-active',active);card.setAttribute('aria-pressed',String(active));card.querySelectorAll('.studio-code,.studio-member').forEach(el=>el.setAttribute('aria-hidden',String(!active)));});if(width<640)schedule();}
 function measure(){width=stage.clientWidth;const small=width<640;cardWidth=small?Math.min(255,width*.68):Math.min(320,width*(cards.length===4?.20:.26));spacing=cardWidth*(small?.94:1.22);cards.forEach(card=>{card.style.width=cardWidth+'px';const rendered=card.querySelector('.device-frame');rendered.style.width='340px';rendered.style.transform=`scale(${cardWidth/340})`;const bottom=card.querySelector('.studio-bottom'),reward=card.querySelector('.studio-reward');if(bottom&&reward)card.style.setProperty('--peek-offset',Math.max(0,bottom.offsetHeight-reward.offsetHeight)+'px');});if(pricing){pricingTop=pricing.getBoundingClientRect().top+scrollY;measurePricingBackdrop(pricing);}schedule();}
 function paint(){frame=0;const rect=stage.getBoundingClientRect(),pop=reduce.matches?0:Math.max(0,Math.min(1,(innerHeight-rect.top)/(innerHeight*.8)));const sway=reduce.matches?0:Math.max(-1,Math.min(1,tiltX+dragOffset));cards.forEach((card,i)=>{const slot=width<640?i-index:cards.length===4?(i-1.5):i===0?0:i%2?Math.ceil(i/2):-Math.ceil(i/2);const rowOffset=0;const z=reduce.matches?0:pop*55-Math.abs(slot)*14;card.style.zIndex=String(10-Math.abs(slot));card.style.transform=`translate(-50%,-50%) translate3d(${slot*spacing+sway*16}px,${Math.abs(slot)*8+rowOffset}px,${z}px) rotateX(${reduce.matches?0:-tiltY*2}deg) rotateY(${reduce.matches?0:-slot*12+sway*7}deg)`;});if(pricing){const progress=reduce.matches?1:Math.max(0,Math.min(1,(scrollY+innerHeight-pricingTop)/(innerHeight*.65)));}}
 function schedule(){if(!frame&&alive)frame=requestAnimationFrame(paint);}
 function move(e){const r=stage.getBoundingClientRect();if(drag){dragOffset=Math.max(-.7,Math.min(.7,(e.clientX-drag.x)/Math.max(240,width)));drag.moved ||= Math.abs(e.clientX-drag.x)>8;}else{return;}schedule();}
 function down(e){if(drag||e.isPrimary===false||e.button!==0)return;drag={x:e.clientX,moved:false,card:e.target.closest('.portrait-card')};stage.setPointerCapture(e.pointerId);stage.classList.add('is-dragging');}
 function up(e){if(!drag)return;if(width<640&&drag.moved){select(Math.max(0,Math.min(cards.length-1,index+(e.clientX<drag.x?1:-1))));}else if(!drag.moved&&drag.card)select(Number(drag.card.dataset.index));suppressClick=drag.moved;drag=null;dragOffset=0;stage.classList.remove('is-dragging');schedule();}
 function cancel(){drag=null;dragOffset=0,suppressClick=false;tiltX=tiltY=0;stage.classList.remove('is-dragging');schedule();}
 function key(e){if(!['ArrowLeft','ArrowRight','Home','Enter',' '].includes(e.key))return;e.preventDefault();const card=e.target.closest('.portrait-card');select(e.key==='Home'?0:e.key==='ArrowLeft'?(index+cards.length-1)%cards.length:e.key==='ArrowRight'?(index+1)%cards.length:card?Number(card.dataset.index):index);}
 function hover(e){if(drag||e.pointerType==='touch')return;const card=e.target.closest('.portrait-card');if(card)select(Number(card.dataset.index));}
 stage.addEventListener('pointermove',move,{passive:true});stage.addEventListener('pointerdown',down);stage.addEventListener('pointerup',up);stage.addEventListener('pointercancel',cancel);stage.addEventListener('pointerleave',()=>{if(!drag&&width>=640){tiltX=tiltY=0;select(0);schedule();}});stage.addEventListener('pointerover',hover);stage.addEventListener('focusin',hover);stage.addEventListener('keydown',key);stage.addEventListener('click',e=>{if(suppressClick){suppressClick=false;return;}const card=e.target.closest('.portrait-card');if(card&&!drag)select(Number(card.dataset.index));});
 window.addEventListener('scroll',schedule,{passive:true});const observer=new ResizeObserver(measure);observer.observe(stage);reduce.addEventListener('change',measure);measure();
 let step=2;const animation=setInterval(()=>{if(document.hidden||reduce.matches||drag)return;const r=stage.getBoundingClientRect();if(r.bottom<0||r.top>innerHeight)return;const nextStep=(step+1)%5;if(showcaseDesigns.some(c=>[c.stampImage,c.stampEmptyImage].filter(Boolean).some(src=>!showcaseReady.has(src)))){prepareShowcaseImages();return;}step=nextStep;cards.forEach((card,i)=>{card.dataset.demoStep=String(step);const fresh=document.createElement('div');fresh.innerHTML=galleryCard(showcaseDesigns[i],step,false);card.querySelectorAll('.studio-stamp').forEach((stamp,n)=>{const next=fresh.querySelectorAll('.studio-stamp')[n],earned=next.classList.contains('earned');stamp.classList.toggle('earned',earned);stamp.title=next.title;const img=stamp.querySelector('img'),nextImg=next.querySelector('img');if(img&&nextImg&&img.getAttribute('src')!==nextImg.getAttribute('src')){img.src=nextImg.getAttribute('src');img.alt=nextImg.alt;stamp.classList.remove('demo-changing');stamp.classList.add('demo-changing');}});for(const selector of ['.studio-balance','.wallet-balance','.studio-points-progress','.studio-reward>span']){const old=card.querySelector(selector),next=fresh.querySelector(selector);if(old&&next)old.innerHTML=next.innerHTML;}if((showcaseDesigns[i].progressDisplay||'icons')!=='icons'){const old=card.querySelector('.studio-stamps'),next=fresh.querySelector('.studio-stamps');if(old&&next)old.innerHTML=next.innerHTML;}const stamps=card.querySelector('.studio-stamps');if(stamps)stamps.setAttribute('aria-label',fresh.querySelector('.studio-stamps').getAttribute('aria-label'));});select(index);paint();},5000);
 stage._cleanup=()=>{alive=false;clearInterval(animation);if(frame)cancelAnimationFrame(frame);observer.disconnect();window.removeEventListener('scroll',schedule);reduce.removeEventListener('change',measure);};select(index);

};
function measurePricingBackdrop(pricing){const grid=pricing.querySelector('.plans-grid');if(!grid)return;const style=getComputedStyle(grid),columns=style.gridTemplateColumns.split(' ').length,rows=Math.ceil(grid.children.length/columns),top=grid.getBoundingClientRect().top-pricing.getBoundingClientRect().top;pricing.style.setProperty('--pricing-backdrop-height',(pricing.offsetHeight-grid.offsetHeight+rows*(pricing.clientWidth<640?330:470)+(rows-1)*parseFloat(style.rowGap||0)+parseFloat(style.paddingTop||0)+parseFloat(style.paddingBottom||0))+'px');}
render();


